-- 000003_migrate_legacy_data.up.sql
-- Generado determinísticamente desde finanzas_miky_go (datos originales).
-- Mapeo: ingresos→pagos, ingreso_fechas_trabajo→dias_trabajados,
-- cuentas→cuentas, split_configuraciones→historial_tasas,
-- splits→splits+transacciones (Business/Box + General residual).

-- Cuentas legadas

-- Pagos (188 ingresos) -- ids originales preservados
SELECT setval('pagos_id_seq', 202, true);

-- Días trabajados (359)

-- Splits (9 pagos) + transacciones (Business/Box originales + General residual)
-- pago 179 monto 65600 -> Business 13100 + Box 19600 + General 32900
-- pago 186 monto 25000 -> Business 5000 + Box 7500 + General 12500
-- pago 187 monto 63100 -> Business 12600 + Box 18900 + General 31600
-- pago 188 monto 61500 -> Business 12300 + Box 18400 + General 30800
-- pago 189 monto 46500 -> Business 9300 + Box 13900 + General 23300
-- pago 198 monto 61500 -> Business 12300 + Box 18400 + General 30800
-- pago 199 monto 110200 -> Business 22000 + Box 33000 + General 55200
-- pago 200 monto 63300 -> Business 12600 + Box 18900 + General 31800
-- pago 201 monto 61500 -> Business 12300 + Box 18400 + General 30800
-- 9 splits, 27 transacciones

-- Verificación final (integridad monetaria por pago)
DO $$
DECLARE
    r RECORD;
BEGIN
    FOR r IN
        SELECT s.pago_id, p.monto_enteros AS pago, COALESCE(SUM(t.monto_enteros),0) AS suma
        FROM splits s JOIN pagos p ON p.id = s.pago_id
        JOIN transacciones t ON t.split_id = s.id
        GROUP BY s.pago_id, p.monto_enteros
    LOOP
        IF r.suma <> r.pago THEN
            RAISE EXCEPTION 'integridad rota en pago %: % <> %', r.pago_id, r.suma, r.pago;
        END IF;
    END LOOP;
END $$;

